from pathlib import Path
from html import escape as e
import json
ROOT=Path(__file__).resolve().parent
all_projects=json.loads((ROOT/'contenuti.json').read_text(encoding='utf8'))['projects']
issues=json.loads((ROOT/'numeri.json').read_text(encoding='utf8'))
def header(prefix=''):
 return f'''<a class="skip" href="#main">Vai al contenuto</a><header class="site-head shell"><a href="{prefix}index.html" class="brand" aria-label="Toolmag, homepage">TOOLMAG<span>*</span></a><p>STRUMENTI UTILI.<br>IDEE DA PROVARE.</p><nav aria-label="Navigazione principale"><a href="{prefix}index.html#archivio">I numeri</a><a href="{prefix}strumenti.html#strumenti">Cerca un tool ↗</a></nav></header>'''
def footer(prefix=''):
 return f'''<footer class="site-footer shell"><a class="brand" href="{prefix}index.html">TOOLMAG<span>*</span></a><p><b>DUE DRITTE</b> / LA NOSTRA RIVISTA</p><a href="https://www.instagram.com/toolmag.ai/" target="_blank" rel="noopener noreferrer">@toolmag.ai ↗</a><small>Licenze diverse per ogni progetto. Hardware e servizi possono avere costi. Requisiti nelle schede.</small></footer>'''
def document(title,body,prefix=''):
 return f'''<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} — TOOLMAG</title><link rel="icon" href="{prefix}assets-toolmag.webp"><link rel="stylesheet" href="{prefix}editoriale.css?v=2"><link rel="stylesheet" href="{prefix}interni.css?v=3"><script defer src="{prefix}interni.js"></script></head><body>{header(prefix)}{body}{footer(prefix)}<dialog class="art-viewer" aria-labelledby="art-title"><header><h2 id="art-title">PAGINA ORIGINALE</h2><button type="button" data-close>CHIUDI ×</button></header><img id="art-image" alt=""><p>Pagina del numero originale · immagini e schemi conservati.</p></dialog></body></html>'''
def visual(p,prefix='',compact=False):
 cls='original-visual '+('schema-visual' if p['visualKind']=='schema' else '')
 return f'''<div class="{cls}"><img src="{prefix}{p['visual']}" alt="{e(p['alt'])}" loading="lazy" width="1080" height="440"></div>'''
def external(url,label):
 return f'<a href="{e(url)}" target="_blank" rel="noopener noreferrer">{label} <span aria-hidden="true">↗</span></a>'
def sources(p):
 if 'imageSource' in p:
  s=p['imageSource'];return f'''<details class="provenance"><summary>IMMAGINE: PROVENIENZA E LIMITI</summary><p>{e(s['kind'])}. {e(s['note'])}</p><p>{e(s['author'])} · {e(s['license'])}</p>{external(s['source'],'Apri la fonte originale')}</details>'''
 return f'''<details class="provenance"><summary>{'DEMO UFFICIALE: PROVENIENZA' if p['visualKind']=='authentic' else 'SCHEMA: COSA STAI GUARDANDO'}</summary><p>{e(p['visualNote'])}</p>{external(p['sourceUrl'],'Apri la fonte originale') if p.get('sourceUrl') else ''}</details>'''
def card(p):
 id=p['id'];name=e(p['name']);primary=p.get('primaryRepository') or p['repository'];mirror=primary!=p['repository']
 links=(external(p['website'],'SITO UFFICIALE') if p.get('website') else '')+external(primary,'REPOSITORY PRINCIPALE' if mirror else 'REPOSITORY')+(external(p['repository'],'MIRROR GITHUB') if mirror else '')
 if p['id']=='scribus':links=external(p['website'],'SITO UFFICIALE')+external(p['repository'],'MIRROR GITHUB')
 terms=' '.join(str(p.get(k,'')) for k in ['name','category','description','requirement','tip1Title','tip1Text','tip2Title','tip2Text'])
 return f'''<article class="project-sheet" id="{id}" data-tool-card data-issue="{p['issue']}" data-kind="{p['group']}" data-search="{e(terms)}"><header class="project-name"><span>{p['position']:02}</span><div><small>{e(p['category'])}</small><h2>{name}</h2></div><b>N. {p['number']}</b></header><h3 class="project-hook">{e(p['hook'])}<br><em>{e(p['hookAccent'])}</em></h3><div class="project-layout"><div class="project-media">{visual(p,'')}<p class="image-credit">{e(p['credit'])}</p><button class="page-open" type="button" data-page="{p['page']}" data-title="{name}">GUARDA LA PAGINA DELLA RIVISTA <span>⊕</span></button>{sources(p)}</div><div class="project-advice"><p class="project-description">{e(p['description'])}</p>{f'<p class="project-context">{e(p["context"])}</p>' if p.get('context') else ''}<div class="tips"><section><span>01 / DUE DRITTE</span><h4>{e(p['tip1Title'])}</h4><p>{e(p['tip1Text'])}</p></section><section><span>02 / DUE DRITTE</span><h4>{e(p['tip2Title'])}</h4><p>{e(p['tip2Text'])}</p></section></div><div class="project-host"><p>{e(p['reaction'])}</p><img src="{p['person']}" alt="Personaggio originale della pagina {name}, con reazione entusiasta" loading="lazy" width="220" height="220"></div></div></div><p class="project-requirement"><b>PRIMA DI PARTIRE</b><span>{e(p['requirement'])}</span></p><div class="project-links">{links}</div></article>'''
def filters(collection=False):
 select='' if collection else '''<label class="kind-label">COSA VUOI FARE?<select id="kind-filter"><option value="all">Tutti gli utilizzi</option><option value="design">Disegno e design</option><option value="immagini">Immagini, foto e 3D</option><option value="documenti">Documenti e ricerche</option><option value="audio">Audio e video</option><option value="modelli">Modelli e chat AI</option><option value="automazioni">Automazioni</option><option value="codice">Codice</option><option value="ricerca-mercati">Ricerca di mercato</option><option value="previsioni">Previsioni sui prezzi</option><option value="test-strategie">Test e simulazione di strategie</option></select></label>'''
 buttons='' if collection else '<div class="issue-filters" role="group" aria-label="Filtra per numero"><button type="button" data-filter="all" aria-pressed="true">TUTTI</button>'+''.join(f'<button type="button" data-filter="{key}" aria-pressed="false">{e(meta["label"])}</button>' for key,meta in issues.items())+'</div>'
 return f'''<div class="search-panel" id="strumenti"><div class="search-fields"><label class="query-label">{'CERCA IN QUESTO NUMERO' if collection else 'CERCA PER NOME O PER IDEA'}<span><input id="tool-query" type="search" placeholder="Prova: foto, documenti, Krita…" autocomplete="off"><button id="clear-query" type="button" aria-label="Cancella ricerca" hidden>×</button></span></label>{select}</div><div class="search-bottom">{buttons}<p id="search-count" aria-live="polite"></p></div></div>'''
empty='''<div class="empty-state" hidden><h2>QUESTO TOOL<br>CI STA SFUGGENDO.</h2><p>Prova un altro termine o togli un filtro.</p><button type="button" data-reset>AZZERA RICERCA E FILTRI ↺</button></div>'''
for issue in issues:
 ps=[p for p in all_projects if p['issue']==issue];number=ps[0]['number'];label=issues[issue]['label']
 title=issues[issue]['titleHtml']
 intro=issues[issue]['intro']
 other_issues=''.join(f'<a class="other-issue" href="speciale-{key}.html">APRI LO SPECIALE {e(meta["label"])} ↗</a>' for key,meta in issues.items() if key!=issue)
 jump=''.join(f'<a href="#{p["id"]}" data-jump="{p["id"]}"><span>{i+1:02}</span>{e(p["name"])}</a>' for i,p in enumerate(ps))
 body=f'''<main id="main"><div class="breadcrumb shell"><a href="index.html#archivio">← L’EDICOLA</a><span>DUE DRITTE / N. {number}</span></div><section class="collection-cover shell"><div><span class="red-kicker">DUE DRITTE · SPECIALE {label}</span><h1>{title}</h1><p>{intro}</p><a href="#indice" class="collection-start">SCEGLI DA DOVE PARTIRE ↓</a></div><a href="assets-speciale-{issue}.webp" target="_blank" aria-label="Guarda la copertina intera"><img src="assets-speciale-{issue}.webp" alt="Copertina originale Speciale {label}" width="720" height="960"></a></section><div class="collection-body shell"><aside class="jump-box" id="indice"><details><summary>IN QUESTO NUMERO <span>10 TOOL ↓</span></summary><nav aria-label="Indice dei progetti">{jump}</nav></details>{other_issues}</aside><div class="sheets">{filters(True)}{empty}{''.join(card(p) for p in ps)}<a class="collection-bottom" href="index.html#archivio">TORNA ALL’EDICOLA ↗</a></div></div></main>'''
 (ROOT/f'speciale-{issue}.html').write_text(document('Speciale '+label,body,''),encoding='utf-8')

tiles=[]
for p in all_projects:
 terms=' '.join(str(p.get(k,'')) for k in ['name','category','description','requirement','tip1Title','tip1Text','tip2Title','tip2Text'])
 tiles.append(f'''<article class="tool-tile" data-tool-card data-issue="{p['issue']}" data-kind="{p['group']}" data-search="{e(terms)}"><a href="speciale-{p['issue']}.html#{p['id']}" aria-label="Scopri {e(p['name'])}"><header><b>{e(p['name'])}</b><span>N. {p['number']}</span></header>{visual(p)}<p class="tile-credit">{'SCHEMA DEL NUMERO' if p['visualKind'] in ['schema','illustration'] else 'IMMAGINE ORIGINALE · FONTE NELLA SCHEDA'}</p><div class="tile-copy"><span>{e(p['category'])}</span><h2>{e(p['hook'])} <em>{e(p['hookAccent'])}</em></h2><p>{e(p['description'])}</p></div><footer><b>SCOPRI COME USARLO</b><span>↗</span></footer></a></article>''')
body=f'''<main id="main"><div class="breadcrumb shell"><a href="index.html">← L’EDICOLA</a><span>L’INDICE TOOLMAG / {len(all_projects)} STRUMENTI</span></div><section class="discovery-hero shell"><div><span class="red-kicker">IDEE DA METTERE IN PRATICA</span><h1>IL TOOL GIUSTO.<br><em>PER LA TUA PROSSIMA IDEA.</em></h1><p>Cerca un nome, un’attività o un problema da risolvere.<br>Qui ritrovi tutti i progetti di Due Dritte.</p></div><div class="discovery-stamp"><b>{len(all_projects)}</b><span>STRUMENTI<br>DA SCOPRIRE</span></div></section><div class="discovery-body shell">{filters()}{empty}<div class="tool-grid">{''.join(tiles)}</div><p class="directory-note">Immagini originali e schemi del numero, indicati nelle schede. Link, requisiti e fonti sempre a portata di mano.</p></div></main>'''
(ROOT/'strumenti.html').write_text(document('Trova il tuo prossimo strumento',body),encoding='utf-8')
print(f'Built {len(issues)} collections and {len(all_projects)} project records.')